create extension if not exists pgcrypto;
create table public.leads(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),project_type text not null,zip varchar(5) not null,timeline text not null,ownership text not null,budget text not null,first_name text not null,last_name text not null,email text not null,phone text not null,consent boolean not null default false,consent_at timestamptz,source text not null default 'direct',score int not null default 0 check(score between 0 and 100),status text not null default 'new' check(status in ('new','contacted','qualified','appointment','won','lost','invalid')),crm_status text not null default 'pending' check(crm_status in ('pending','sent','failed')),crm_synced_at timestamptz,user_agent text);
create index leads_created_at_idx on public.leads(created_at desc);create index leads_status_score_idx on public.leads(status,score desc);create index leads_phone_idx on public.leads(phone);
create table public.crm_outbox(id bigint generated always as identity primary key,lead_id uuid not null references public.leads(id) on delete cascade,payload jsonb not null,attempts int not null default 0,next_attempt_at timestamptz not null default now(),last_error text,created_at timestamptz not null default now());
alter table public.leads enable row level security;alter table public.crm_outbox enable row level security;
comment on table public.leads is 'First-party remodeling leads; server writes use the service role.';
